import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), threshold = sc.nextInt();
        int streak = 0;
        for (int i = 0; i < n; i++) {
            int v = sc.nextInt();
            streak = v > threshold ? streak + 1 : 0;
            if (streak == 3) {
                System.out.println(i - 2);
                return;
            }
        }
        System.out.println(-1);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, threshold int
	fmt.Fscan(in, &n, &threshold)
	streak := 0
	for i := 0; i < n; i++ {
		var v int
		fmt.Fscan(in, &v)
		if v > threshold {
			streak++
		} else {
			streak = 0
		}
		if streak == 3 {
			fmt.Println(i - 2)
			return
		}
	}
	fmt.Println(-1)
}
